/**
 * 快捷鍵插件
 *
 * 提供可配置的鍵盤快捷鍵支援
 * 支援自定義快捷鍵映射和全局/局部模式
 */

import type { MpvPlugin, PluginInstance } from '../../core/types/plugin';
import type { MpvVideoElement } from '../../renderer/ui/MpvVideoElement';

/**
 * 快捷鍵動作類型
 */
export type KeyboardAction = (player: MpvVideoElement, event: KeyboardEvent) => void;

/**
 * 快捷鍵映射
 */
export interface KeyboardShortcut {
    /** 按鍵（KeyboardEvent.key） */
    key: string;

    /** 是否需要 Ctrl/Cmd */
    ctrl?: boolean;

    /** 是否需要 Shift */
    shift?: boolean;

    /** 是否需要 Alt */
    alt?: boolean;

    /** 動作函數 */
    action: KeyboardAction;

    /** 描述（用於幫助文檔） */
    description?: string;
}

/**
 * 快捷鍵插件配置
 */
export interface KeyboardPluginOptions {
    /** 自定義快捷鍵（會與預設合併） */
    shortcuts?: KeyboardShortcut[];

    /** 是否啟用全局快捷鍵（即使播放器未聚焦也生效） */
    global?: boolean;

    /** 是否在輸入框中禁用快捷鍵 */
    disableInInputs?: boolean;

    /** 是否顯示快捷鍵提示 */
    showHints?: boolean;

    /** seek 步進（秒） */
    seekStep?: number;

    /** 音量步進（0-1） */
    volumeStep?: number;
}

/**
 * 預設快捷鍵
 */
const DEFAULT_SHORTCUTS: KeyboardShortcut[] = [
    // 播放控制
    {
        key: ' ',
        action: (player) => player.paused ? player.play() : player.pause(),
        description: '播放/暫停',
    },
    {
        key: 'k',
        action: (player) => player.paused ? player.play() : player.pause(),
        description: '播放/暫停',
    },

    // Seeking
    {
        key: 'ArrowLeft',
        action: (player, e) => {
            const step = e.shiftKey ? 1 : 5;
            player.currentTime = Math.max(0, player.currentTime - step);
        },
        description: '後退 5 秒 (Shift: 1 秒)',
    },
    {
        key: 'ArrowRight',
        action: (player, e) => {
            const step = e.shiftKey ? 1 : 5;
            player.currentTime = Math.min(player.duration, player.currentTime + step);
        },
        description: '前進 5 秒 (Shift: 1 秒)',
    },
    {
        key: 'j',
        action: (player) => {
            player.currentTime = Math.max(0, player.currentTime - 10);
        },
        description: '後退 10 秒',
    },
    {
        key: 'l',
        action: (player) => {
            player.currentTime = Math.min(player.duration, player.currentTime + 10);
        },
        description: '前進 10 秒',
    },
    {
        key: 'Home',
        action: (player) => {
            player.currentTime = 0;
        },
        description: '跳到開頭',
    },
    {
        key: 'End',
        action: (player) => {
            player.currentTime = player.duration;
        },
        description: '跳到結尾',
    },

    // 幀步進
    {
        key: ',',
        action: (player) => {
            const fps = (player as any).fps ?? 24;
            player.currentTime = Math.max(0, player.currentTime - 1 / fps);
        },
        description: '上一幀',
    },
    {
        key: '.',
        action: (player) => {
            const fps = (player as any).fps ?? 24;
            player.currentTime = Math.min(player.duration, player.currentTime + 1 / fps);
        },
        description: '下一幀',
    },

    // 音量
    {
        key: 'ArrowUp',
        action: (player) => {
            player.volume = Math.min(1, player.volume + 0.05);
        },
        description: '增加音量',
    },
    {
        key: 'ArrowDown',
        action: (player) => {
            player.volume = Math.max(0, player.volume - 0.05);
        },
        description: '減少音量',
    },
    {
        key: 'm',
        action: (player) => {
            player.muted = !player.muted;
        },
        description: '靜音切換',
    },

    // 播放速度
    {
        key: '[',
        action: (player) => {
            player.playbackRate = Math.max(0.25, player.playbackRate - 0.25);
        },
        description: '降低播放速度',
    },
    {
        key: ']',
        action: (player) => {
            player.playbackRate = Math.min(8, player.playbackRate + 0.25);
        },
        description: '增加播放速度',
    },
    {
        key: '\\',
        action: (player) => {
            player.playbackRate = 1;
        },
        description: '重置播放速度',
    },

    // 全螢幕
    {
        key: 'f',
        action: (player) => {
            if (document.fullscreenElement) {
                document.exitFullscreen();
            } else {
                player.requestFullscreen?.();
            }
        },
        description: '全螢幕切換',
    },
    {
        key: 'Escape',
        action: () => {
            if (document.fullscreenElement) {
                document.exitFullscreen();
            }
        },
        description: '退出全螢幕',
    },

    // 循環
    {
        key: 'o',
        action: (player) => {
            player.loop = !player.loop;
        },
        description: '循環播放切換',
    },

    // 數字鍵快速跳轉（0-9 對應 0%-90%）
    ...Array.from({ length: 10 }, (_, i) => ({
        key: String(i),
        action: (player: MpvVideoElement) => {
            player.currentTime = player.duration * (i / 10);
        },
        description: `跳到 ${i * 10}%`,
    })),
];

/**
 * 快捷鍵插件定義
 */
export const KeyboardPlugin: MpvPlugin<KeyboardPluginOptions> = {
    name: 'keyboard',
    version: '1.0.0',

    install(player, options = {}) {
        return new KeyboardManager(player, {
            shortcuts: [...DEFAULT_SHORTCUTS, ...(options.shortcuts ?? [])],
            global: options.global ?? false,
            disableInInputs: options.disableInInputs ?? true,
            showHints: options.showHints ?? false,
            seekStep: options.seekStep ?? 5,
            volumeStep: options.volumeStep ?? 0.05,
        });
    },
};

/**
 * 快捷鍵管理器
 */
export class KeyboardManager implements PluginInstance {
    readonly name = 'keyboard';

    private player: MpvVideoElement;
    private options: Required<KeyboardPluginOptions>;
    private shortcuts: Map<string, KeyboardShortcut[]> = new Map();
    private _enabled = true;
    private keydownHandler: (e: KeyboardEvent) => void;

    constructor(player: MpvVideoElement, options: Required<KeyboardPluginOptions>) {
        this.player = player;
        this.options = options;

        // 建立快捷鍵索引
        for (const shortcut of options.shortcuts) {
            const key = this.normalizeKey(shortcut.key);
            if (!this.shortcuts.has(key)) {
                this.shortcuts.set(key, []);
            }
            this.shortcuts.get(key)!.push(shortcut);
        }

        // 綁定事件處理器
        this.keydownHandler = this.handleKeydown.bind(this);

        if (options.global) {
            document.addEventListener('keydown', this.keydownHandler);
        } else {
            player.addEventListener('keydown', this.keydownHandler);
        }

        // 確保播放器可聚焦
        if (player.tabIndex < 0) {
            player.tabIndex = 0;
        }
    }

    /**
     * 標準化按鍵名稱
     */
    private normalizeKey(key: string): string {
        return key.toLowerCase();
    }

    /**
     * 處理按鍵事件
     */
    private handleKeydown(event: KeyboardEvent): void {
        if (!this._enabled) return;

        // 檢查是否在輸入框中（使用 composedPath 支援 Shadow DOM）
        if (this.options.disableInInputs) {
            const path = event.composedPath();
            for (const el of path) {
                if (el instanceof HTMLElement) {
                    const tagName = el.tagName;
                    if (tagName === 'INPUT' || tagName === 'TEXTAREA' || el.isContentEditable) {
                        return;
                    }
                }
            }
        }

        const key = this.normalizeKey(event.key);
        const shortcuts = this.shortcuts.get(key);

        if (!shortcuts) return;

        // 找到匹配的快捷鍵
        const matched = shortcuts.find(s => {
            if (s.ctrl && !event.ctrlKey && !event.metaKey) return false;
            if (s.shift && !event.shiftKey) return false;
            if (s.alt && !event.altKey) return false;
            return true;
        });

        if (matched) {
            event.preventDefault();
            event.stopPropagation();
            matched.action(this.player, event);
        }
    }

    // ===== 公開 API =====

    /**
     * 添加快捷鍵
     */
    addShortcut(shortcut: KeyboardShortcut): void {
        const key = this.normalizeKey(shortcut.key);
        if (!this.shortcuts.has(key)) {
            this.shortcuts.set(key, []);
        }
        this.shortcuts.get(key)!.push(shortcut);
    }

    /**
     * 移除快捷鍵
     */
    removeShortcut(key: string, action?: KeyboardAction): void {
        const normalizedKey = this.normalizeKey(key);
        const shortcuts = this.shortcuts.get(normalizedKey);

        if (!shortcuts) return;

        if (action) {
            const index = shortcuts.findIndex(s => s.action === action);
            if (index !== -1) {
                shortcuts.splice(index, 1);
            }
        } else {
            this.shortcuts.delete(normalizedKey);
        }
    }

    /**
     * 獲取所有快捷鍵
     */
    getShortcuts(): KeyboardShortcut[] {
        const all: KeyboardShortcut[] = [];
        for (const shortcuts of this.shortcuts.values()) {
            all.push(...shortcuts);
        }
        return all;
    }

    /**
     * 啟用快捷鍵
     */
    enable(): void {
        this._enabled = true;
    }

    /**
     * 禁用快捷鍵
     */
    disable(): void {
        this._enabled = false;
    }

    /**
     * 是否啟用
     */
    get enabled(): boolean {
        return this._enabled;
    }

    /**
     * 銷毀插件
     */
    destroy(): void {
        if (this.options.global) {
            document.removeEventListener('keydown', this.keydownHandler);
        } else {
            this.player.removeEventListener('keydown', this.keydownHandler);
        }
        this.shortcuts.clear();
    }
}

